"""AI-Generated Unit Tests for QualityRuleEngine."""

import pytest
from quality_assessment.rule_engine import (
    QualityRuleEngine,
    RuleCondition,
    ComparisonOperator,
    LogicalOperator,
    RuleEvaluationError,
)


class TestQualityRuleEngineAI:
    """Test suite generated by AI for QualityRuleEngine."""

    def test_evaluate_condition_gt(self):
        """Test greater-than comparison condition."""
        cond = RuleCondition("coverage", ComparisonOperator.GT, 80.0)
        assert QualityRuleEngine.evaluate_condition(cond, {"coverage": 85.0}) is True
        assert QualityRuleEngine.evaluate_condition(cond, {"coverage": 75.0}) is False

    def test_evaluate_condition_eq(self):
        """Test equality comparison condition."""
        cond = RuleCondition("status", ComparisonOperator.EQ, "ready")
        assert QualityRuleEngine.evaluate_condition(cond, {"status": "ready"}) is True
        assert QualityRuleEngine.evaluate_condition(cond, {"status": "pending"}) is False

    def test_evaluate_rule_group_and(self):
        """Test AND rule group evaluation."""
        cond1 = RuleCondition("coverage", ComparisonOperator.GTE, 80.0)
        cond2 = RuleCondition("complexity", ComparisonOperator.LT, 5.0)
        payload = {"coverage": 85.0, "complexity": 3.0}
        res = QualityRuleEngine.evaluate_rule_group([cond1, cond2], payload, LogicalOperator.AND)
        assert res is True

    def test_evaluate_rule_group_or(self):
        """Test OR rule group evaluation."""
        cond1 = RuleCondition("coverage", ComparisonOperator.GTE, 90.0)
        cond2 = RuleCondition("complexity", ComparisonOperator.LT, 5.0)
        payload = {"coverage": 70.0, "complexity": 3.0}
        res = QualityRuleEngine.evaluate_rule_group([cond1, cond2], payload, LogicalOperator.OR)
        assert res is True

    def test_missing_field_strict_mode(self):
        """Test missing field in strict mode raises error."""
        cond = RuleCondition("missing", ComparisonOperator.EQ, 1)
        with pytest.raises(RuleEvaluationError):
            QualityRuleEngine.evaluate_condition(cond, {"present": 1}, strict_missing=True)
